hboard-card" data-animate="fade-up" style="margin-bottom:1.5rem;"><div class="section-heading compact" style="display:flex;justify-content:space-between;align-items:center;gap:1rem;flex-wrap:wrap;"><div><span class="section-kicker">Saved</span><h2>My Favorites</h2></div><a href="favorites.php" class="btn-outline">View All</a></div><?php if(empty($favorites)): ?><div class="admin-empty-state"><i class="fas fa-heart" style="font-size:3rem;color:var(--text-lighter);margin-bottom:1rem;"></i><p class="muted-text">You have not saved any rooms yet.</p><a href="rooms.php" class="btn-primary">Browse Rooms</a></div><?php else: ?><div class="room-grid" style="grid-template-columns:repeat(auto-fill,minmax(240px,1fr));padding:0;"><?php foreach(array_slice($favorites,0,4) as $room): ?><article class="room-card" onclick="window.location.href='room-detail.php?id=<?php echo $room['id']; ?>'"><div class="card-image" style="height:150px;"><img src="<?php echo getRoomImageUrl($room['primary_image'] ?? null); ?>"></div><div class="card-content"><div class="card-price">Rs. <?php echo number_format((float)$room['price']); ?><span>/month</span></div><h3 class="card-title"><?php echo htmlspecialchars($room['title']); ?></h3></div></article><?php endforeach; ?></div><?php endif; ?></div><div class="dashboard-card" data-animate="fade-up"><div class="section-heading compact" style="display:flex;justify-content:space-between;align-items:center;gap:1rem;flex-wrap:wrap;"><div><span class="section-kicker">Explore</span><h2>Recent Listings</h2></div><a href="rooms.php" class="btn-outline">View All</a></div><?php $recent=searchRooms([],1,4); if(!empty($recent['rooms'])): ?><div class="room-grid" style="grid-template-columns:repeat(auto-fill,minmax(240px,1fr));padding:0;"><?php foreach($recent['rooms'] as $room): ?><article class="room-card" onclick="window.location.href='room-detail.php?id=<?php echo $room['id']; ?>'"><div class="card-image" style="height:150px;"><img src="<?php echo getRoomImageUrl